def grid_to_dict(df: pd.DataFrame) -> dict[str, dict[str, float]]:
    ordered = df.sort_index().sort_index(axis=1)
    return {
        str(column): {str(index): float(value) for index, value in values.items()}
        for column, values in ordered.to_dict().items()
    }


