import pandas as pd
import pytest
from main import build_engagement_grid

TestCase = tuple[str, list[dict[str, object]], dict[str, dict[str, int]]]


def grid_to_dict(grid: pd.DataFrame | pd.Series) -> dict[str, dict[str, int]]:
    frame = grid.to_frame() if isinstance(grid, pd.Series) else grid
    return {
        str(cohort): {str(offset): int(value) for offset, value in row.items()}
        for cohort, row in frame.iterrows()
    }


run_cases: list[TestCase] = [
    (
        "events per cohort by month offset",
        [
            {"user_id": "U1", "timestamp": pd.Timestamp("2024-01-05")},
            {"user_id": "U1", "timestamp": pd.Timestamp("2024-02-10")},
            {"user_id": "U2", "timestamp": pd.Timestamp("2024-01-15")},
            {"user_id": "U2", "timestamp": pd.Timestamp("2024-01-20")},
            {"user_id": "U3", "timestamp": pd.Timestamp("2024-02-01")},
        ],
        {
            "2024-01": {"0": 3, "1": 1},
            "2024-02": {"0": 1, "1": 0},
        },
    ),
]

submit_cases: list[TestCase] = [
    (
        "single cohort across three months",
        [
            {"user_id": "A", "timestamp": pd.Timestamp("2024-05-02")},
            {"user_id": "A", "timestamp": pd.Timestamp("2024-06-02")},
            {"user_id": "A", "timestamp": pd.Timestamp("2024-07-02")},
            {"user_id": "B", "timestamp": pd.Timestamp("2024-05-20")},
            {"user_id": "B", "timestamp": pd.Timestamp("2024-05-25")},
        ],
        {
            "2024-05": {"0": 3, "1": 1, "2": 1},
        },
    ),
]
submit_cases = [pytest.param(*case, marks=pytest.mark.submit) for case in submit_cases]


@pytest.mark.parametrize(("name", "events_data", "expected"), run_cases + submit_cases)
def test_build_engagement_grid(
    name: str,
    events_data: list[dict[str, object]],
    expected: dict[str, dict[str, int]],
) -> None:
    print("\n---------------------------------")
    print(f"Case: {name}")
    print(f"Expected grid: {expected}")
    events = pd.DataFrame(events_data)
    result = build_engagement_grid(events)
    actual = grid_to_dict(result)
    print(f"Actual grid:   {actual}")
    assert actual == expected

